#include <cstdio>
#include <vector>

int main()
{
	int N;
	long long c0, c1;
	scanf("%d%lld%lld", &N, &c0, &c1);

	std::vector<long long> f(N + 1);
	f[1] = 0;

	for (int i = 2, lc = 1; i <= N; ++i)
	{
		if (i - lc > 1 &&
			f[lc] + f[i - lc] >
			f[lc + 1] + f[i - lc - 1] + c0 - c1)
			++lc;

		f[i] = f[lc] + f[i - lc]
		     + static_cast<long long>(lc) * c0
		     + static_cast<long long>(i - lc) * c1;
	}

	printf("%lld\n", f[N]);
	return 0;
}

